"""Derives Test-KillUnconscious-v1271.ps1 from Test-PairedVictim-v1248l.ps1 for stage 4 (#14): a death outside the
shared combat outcome. The source chokes the Dunwall upper-floor tutorial guard 2 under the product controller (both
worlds must agree it is unconscious), then kills the unconscious body with sword attacks while looking down at it. No
combat channel binds an unconscious NPC, so the host kill reaches the client only through the 1214n Dead
reconciliation (host -> client). Pass (runtime): the guard ends dead in both worlds. Recorded: which path shared the
death (stream deathShare, reconciliation counters) and both windows on video."""
from pathlib import Path
P = Path(__file__).resolve().parent
s = P.joinpath('Test-PairedVictim-v1248l.ps1').read_bytes().decode('utf-8'); nl = '\r\n' if '\r\n' in s else '\n'
def rep(old, new, count=1):
    global s
    n = s.count(old); assert n == count, (n, old[:90]); s = s.replace(old, new)
rep("param([ValidatePattern('^[a-z0-9-]+$')][string]$Take='paired-victim-product-v1248l',[string]$Candidate='candidate-npc-combat-v1214c',[string[]]$Sources=@('client','host'),[string[]]$Kinds=@('choke','lethal'))",
    "param([ValidatePattern('^[a-z0-9-]+$')][string]$Take='kill-unconscious-v1271a',[string]$Candidate='candidate-npc-combat-v1214v',[string[]]$Sources=@('host'),[string[]]$Kinds=@('choke'),[int]$KillAttempts=15)")
rep("# 1248l (1214c): every census-1253 takedown scene is a partner phase;",
    "# 1271 (stage 4, #14, 1214n): after the choke the source kills the unconscious guard; no combat channel binds an unconscious NPC,"
    + nl + "# so the death reaches the peer only by the Dead reconciliation. Generated by make_kill_unconscious_v1271.py from 1248l." + nl
    + "# 1248l (1214c): every census-1253 takedown scene is a partner phase;")
rep("operation='PairedVictim1248l'", "operation='KillUnconscious1271'", 2)
rep("'-t','13'", "'-t','34'")
kill = r'''   # 1271: kill the unconscious body (sword attacks, looking down from ~1.1 m), then let the reconciliation run.
   # 1271c: the ragdoll lies at the source's feet, not at the guard's recorded root (1271b swung at an empty aisle):
   # look down in place, then sweep the yaw around the source's own position.
   # 1271h: pitch stays within the helper's 70 degrees; the source position falls back to --player; kill rows and both peers'
   # combat status are saved before any failure.
   $killRows=[Collections.Generic.List[object]]::new();$killed=$false;$me=try{(Q $source '--player-states').position}catch{(Q $source '--player').candidatePosition}
   $plan=[Collections.Generic.List[object]]::new();foreach($pv in 45,60,70){$plan.Add(@{yaw=$null;pitch=$pv})};foreach($yv in 0..11){$plan.Add(@{yaw=$yv*30;pitch=60})}
   try{for($k=0;$k-lt[Math]::Min($plan.Count,$KillAttempts)-and!$killed;$k++){$step=$plan[$k]
    if($null-ne$step.yaw){C $source ('setviewpos {0} {1} {2} {3} 0' -f (F $me[0]),(F $me[1]),(F ([double]$me[2]+1.7)),([double]$step.yaw).ToString('F4',$inv));Start-Sleep -Milliseconds 350}
    try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch $step.pitch -Quick|Out-Null}catch{} # 1271l: an unsettled pitch is not a failure
    & "$lab/Send-D2Input.ps1" -Role $source -RightTrigger 255 -DurationMs 220|Out-Null;Start-Sleep -Milliseconds 900
    $h=try{Q $source '--health' $row.guardHandleSource}catch{$null};$killed=(!$h-or$h.current-le0)
    $killRows.Add([pscustomobject]@{attempt=$k;yaw=$step.yaw;pitch=$step.pitch;health=$h.current;suppressed=$h.ownerSuppressed;killed=$killed})}
   }finally{Save "$out/$key-kill.json" @($killRows)}
  $row.killAttempts=$killRows.Count
   foreach($q in 'host','client'){foreach($suffix in '.npc-stream.json','.npc-combat.json'){try{Copy-Item -LiteralPath "$root/work/lab-instances/$q/coop-status.json$suffix" -Destination "$out/$key-kill-$q$suffix" -ErrorAction Stop}catch{}}}
   if(!$killed){throw 'The source did not kill the unconscious guard'};$row.checks.Add("Source killed the unconscious guard (attempt $($killRows.Count))")
   try{& "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $source -Pitch 0 -Quick|Out-Null}catch{}
   $recon=[Collections.Generic.List[object]]::new();$rw=[Diagnostics.Stopwatch]::StartNew()
   do{Start-Sleep -Milliseconds 400;$oh=try{Q $peer '--health' $row.guardHandleObserver}catch{$null}
    $sns=try{S $source '.npc-stream.json'}catch{$null};$ons=try{S $peer '.npc-stream.json'}catch{$null}
    $se=if($sns){@($sns.entries|Where-Object {$_.handle-eq$row.guardHandleSource})|Select-Object -First 1}else{$null};$oe=if($ons){@($ons.entries|Where-Object {$_.handle-eq$row.guardHandleObserver})|Select-Object -First 1}else{$null}
    $recon.Add([pscustomobject]@{ms=$rw.ElapsedMilliseconds;observerHealth=$oh.current;observerSuppressed=$oh.ownerSuppressed;sourceShare=$se.deathShare;sourceCorpse=$se.corpse;sourceDeadSends=$se.deadSends;observerShare=$oe.deathShare;observerCorpse=$oe.corpse;
     sourceRelevance=$sns.relevance|Select-Object deadReconciled,deadSent,combatSharedDeaths;observerRelevance=$ons.relevance|Select-Object clientDeadApplied,clientDeadAlready,clientDeadRefused,clientDeadLast,reconcileDecl})}
   while($rw.ElapsedMilliseconds-lt6000-and!(!$oh-or$oh.current-le0))
   Start-Sleep -Milliseconds 1500;Save "$out/$key-reconcile.json" @($recon)
   foreach($q in 'host','client'){foreach($suffix in '.npc-stream.json','.npc-combat.json'){try{Copy-Item -LiteralPath "$root/work/lab-instances/$q/coop-status.json$suffix" -Destination "$out/$key-after-kill-$q$suffix" -ErrorAction Stop}catch{}}}
   $after=[ordered]@{source=(& $readHealth $source $row.guardHandleSource);observer=(& $readHealth $peer $row.guardHandleObserver)}
   $deaths=@{};foreach($q in 'host','client'){$deaths[$q]=try{(S $q '.npc-combat.json').deaths}catch{0}}
   $row.killOutcome=[ordered]@{source=(& $outcome $after.source $source);observer=(& $outcome $after.observer $peer)}
   $last=$recon[$recon.Count-1];$row.deathShare=[ordered]@{source=$last.sourceShare;observer=$last.observerShare;sourceRelevance=$last.sourceRelevance;observerRelevance=$last.observerRelevance}
   if($row.killOutcome.source-ne'dead'-or$row.killOutcome.observer-ne'dead'){throw "Kill outcome differs: source $($row.killOutcome.source), observer $($row.killOutcome.observer)"}
   $row.checks.Add("Unconscious guard killed by the $source is dead in both worlds (share: source $($last.sourceShare), observer $($last.observerShare))")
'''
anchor = "   $sv=try{(Guard $source).position}catch{$null};$ov=try{(Guard $peer).position}catch{$null};$row.victimEnd=[ordered]@{source=$sv;observer=$ov}"
rep(anchor, kill.replace('\n', nl) + anchor)
rep("scope='paired_victim_alignment: rear choke under the product controller (NPC stream on, natural guard AI), both source roles; partner phases and the observer-world victim recorded; fixture restored after every case.'",
    "scope='Stage 4 unshared death: the source chokes the Dunwall tutorial guard under the product controller, then kills the unconscious body; the guard must end dead in both worlds (1214n Dead reconciliation); fixture restored after every case.'")
rep('"PASS_PAIRED_VICTIM $($rows.Count) cases"', '"PASS_KILL_UNCONSCIOUS $($rows.Count) cases"')
P.joinpath('Test-KillUnconscious-v1271.ps1').write_bytes(s.encode('utf-8'))
print('ok')
